<template>
  <div class="workbench api-sources">
    <header class="wb-header"><div><span class="wb-eyebrow">GET JSON / 认证来源</span><h1>把外部记录变成可审阅的候选</h1><p>固定来源版本，逐页保留读取证据。候选经过处理与审批后才能发布。</p></div><button :disabled="loading" @click="load()">刷新列表</button></header>
    <p v-if="error" class="wb-error" role="alert">{{ error }}</p><p v-if="notice" class="wb-notice" role="status">{{ notice }}</p>
    <div class="api-grid">
      <section class="wb-panel" aria-labelledby="sources-title"><div class="wb-section-head"><h2 id="sources-title">我的 API 来源</h2><button @click="newSource">＋ 配置来源</button></div>
        <p v-if="loading" role="status">正在读取…</p><p v-if="sourceError" class="wb-error" role="alert">{{ sourceError }}</p><p v-else-if="!loading && !sources.length" class="wb-muted">尚未配置来源。先登记凭据，再绑定 HTTPS 接口。</p>
        <ul class="source-list"><li v-for="source in sources" :key="source.id"><div><strong>{{ source.name }}</strong><span>v{{ source.version }} · {{ source.enabled ? '启用' : '已停用' }}</span><small>{{ source.config.url }}</small><small>水位：{{ source.watermark || '尚未提交完整快照' }}</small></div><div class="source-actions"><button :disabled="busy" @click="edit(source)">配置</button><button v-if="source.active_run" @click="openRun(source.active_run)">查看在途任务</button><button v-else :disabled="busy || !source.enabled" @click="start(source)">采集此版本</button><button :disabled="busy" @click="toggle(source)">{{ source.enabled ? '停用来源' : '启用来源' }}</button></div></li></ul><button v-if="sourceCursor" :disabled="loading" @click="load(true)">继续读取来源</button>
      </section>
      <section class="wb-panel" aria-labelledby="credentials-title"><h2 id="credentials-title">受管凭据</h2><p class="wb-muted">凭据仅发送至绑定的 HTTPS 域名与端口。保存后不再返回密钥；停用会立即阻断来源及产物读取。</p><p v-if="credentialError" class="wb-error" role="alert">{{ credentialError }}</p>
        <ul class="credential-list"><li v-for="item in credentials" :key="item.id"><strong>{{ item.name }}</strong><small>{{ item.origin }} · {{ item.kind }} · {{ item.enabled ? '启用' : '已停用' }}</small><button v-if="item.enabled" :disabled="busy" @click="disableCredential(item.id)">停用凭据</button></li></ul><button v-if="credentialCursor" :disabled="loading" @click="load(true)">继续读取凭据</button>
        <details><summary>登记新凭据</summary><form class="wb-stack" aria-label="登记 API 凭据" @submit.prevent="createCredential"><fieldset :disabled="busy"><label class="wb-label">凭据名称<input v-model="credential.name" required maxlength="128" /></label><label class="wb-label">绑定来源<input v-model="credential.origin" type="url" required placeholder="https://api.example.com/" /></label><label class="wb-label">认证方式<select v-model="credential.kind"><option value="bearer">Bearer Token</option><option value="api_key">X-API-Key</option></select></label><label class="wb-label">密钥<input v-model="credential.secret" type="password" autocomplete="new-password" minlength="16" maxlength="4096" required /></label></fieldset><button class="primary" :disabled="busy">加密保存凭据</button></form></details>
      </section>
    </div>
    <section v-if="editing" class="wb-panel" aria-label="配置 API 来源"><div class="wb-section-head"><h2>{{ editing.id ? `编辑 ${editing.name} · 保存为新版本` : '配置新的 JSON 来源' }}</h2><button :disabled="busy" @click="editing = null">收起</button></div><form class="wb-stack" @submit.prevent="saveSource"><fieldset :disabled="busy"><div class="wb-form"><label class="wb-label">来源名称<input v-model="editing.name" maxlength="128" required /></label><label class="wb-label">已登记凭据<select v-model="editing.config.credential_id" aria-label="已登记凭据" required><option value="">选择凭据</option><option v-for="item in credentials.filter(item => item.enabled)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.origin }}</option></select></label><label class="wb-label api-wide">GET 地址<input v-model="editing.config.url" type="url" required placeholder="https://api.example.com/records" /></label><label class="wb-label">记录数组位置<input v-model="editing.config.items_pointer" placeholder="/data/items；根数组留空" /></label><label class="wb-label">稳定记录键<input v-model="editing.config.record_key" required placeholder="id" /></label><label class="wb-label">分页方式<select v-model="editing.config.pagination.mode"><option value="none">单页</option><option value="page">页码</option><option value="cursor">游标</option></select></label><template v-if="editing.config.pagination.mode !== 'none'"><label class="wb-label">请求参数名<input v-model="editing.config.pagination.parameter" required placeholder="page 或 cursor" /></label><label class="wb-label">后续页面标记位置<input v-model="editing.config.pagination.next_pointer" required placeholder="/has_more 或 /next_cursor" /></label></template></div>
        <p class="wb-muted">页码模式要求后续标记为布尔值；游标模式要求字符串，null 或空字符串表示结束。记录键相同且内容相同才会去重；同键不同内容会停止。</p>
        <details><summary>一致性、增量与读取上限</summary><div class="wb-form"><label class="wb-label">快照令牌位置<input v-model="editing.config.pagination.snapshot_pointer" placeholder="可选，例如 /snapshot" /></label><label class="wb-label">快照请求参数<input v-model="editing.config.pagination.snapshot_parameter" placeholder="与令牌位置成对填写" /></label><label class="wb-label">增量时间列<input v-model="editing.config.watermark_field" placeholder="可选，RFC3339 时间" /></label><label class="wb-label">水位请求参数<input v-model="editing.config.watermark_parameter" placeholder="例如 updated_since" /></label><label class="wb-label">删除标记列<input v-model="editing.config.deleted_field" placeholder="可选，布尔值" /></label><label class="wb-label">最多页数<input v-model.number="editing.config.limits.max_pages" type="number" min="1" max="100" required /></label><label class="wb-label">最多记录<input v-model.number="editing.config.limits.max_records" type="number" min="1" max="10000" required /></label><label class="wb-label">单页字节上限<input v-model.number="editing.config.limits.max_page_bytes" type="number" min="1024" max="8388608" required /></label><label class="wb-label">总字节上限<input v-model.number="editing.config.limits.max_bytes" type="number" min="1024" max="33554432" required /></label><label class="wb-label">总请求上限<input v-model.number="editing.config.limits.max_requests" type="number" min="1" max="200" required /></label><label class="wb-label">总时限（秒）<input v-model.number="editing.config.limits.timeout_seconds" type="number" min="1" max="300" required /></label></div></details><p class="wb-muted">没有快照令牌时只记录实际读取范围，中断后不能跨快照续接。删除检测只认显式布尔标记，不把缺失记录推断成删除。水位仅在完整候选提交后推进。</p></fieldset><button class="primary" :disabled="busy">保存来源版本</button></form></section>
    <section v-if="runID" class="wb-panel" aria-labelledby="run-title"><div class="wb-section-head"><h2 id="run-title">采集回执</h2><button :disabled="busy" @click="refreshRun">重新读取</button></div><p v-if="runLoading" role="status">正在核对持久任务…</p><template v-if="run"><p><strong>{{ statusLabel(run.status) }}</strong> · 来源 v{{ run.source_version }} · {{ run.id }}</p><p v-if="run.error" class="wb-error">{{ run.error }}</p><dl class="receipt-stats"><div><dt>已读取页面</dt><dd>{{ run.pages?.length || 0 }}</dd></div><div><dt>保留记录</dt><dd>{{ run.record_count }}</dd></div><div><dt>相同记录去重</dt><dd>{{ run.duplicate_count }}</dd></div><div><dt>显式删除标记</dt><dd>{{ run.deleted_count }}</dd></div></dl><p>{{ run.consistency.includes('provider_snapshot') ? '来源提供固定快照令牌；该保证由来源服务提供。' : '来源未提供可验证的跨页一致性保证，只表示已读取范围。' }}</p><p v-if="run.status !== 'completed'" class="wb-muted">此任务不代表完整快照，水位未推进。已提交或已读取的历史事实会保留。</p><div class="source-actions"><button v-if="!terminal(run.status)" :disabled="busy" @click="mutateRun('cancel')">请求取消</button><button v-if="run.retryable" :disabled="busy" @click="mutateRun('resume')">从原快照检查点继续</button><RouterLink v-for="ref in run.output_refs || []" :key="ref.asset_id" :to="{ path: '/analysis', query: { asset: `${ref.asset_id}:${ref.version}` } }">查看候选产物 {{ ref.asset_id.slice(0, 8) }} ↗</RouterLink><RouterLink v-if="run.output_refs?.length" to="/pipelines">进入处理与发布</RouterLink></div><details><summary>逐页读取证据</summary><ol><li v-for="page in run.pages" :key="page.number">第 {{ page.number }} 页 · {{ page.records }} 条 · {{ page.bytes }} 字节 · {{ page.acquired_at }}<code>{{ page.digest }}</code></li></ol></details></template></section>
  </div>
</template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
import { apiSourceApi as api, type APICredential, type APISource, type APIIngestionRun, type SourceConfig } from '@/api/apisource'
import '@/components/workbench/workbench.css'
const auth = useAuthStore(), route = useRoute(), router = useRouter()
const sources = ref<APISource[]>([]), credentials = ref<APICredential[]>([]), sourceCursor = ref(''), credentialCursor = ref('')
const editing = ref<{ id?: string; name: string; version?: number; config: SourceConfig } | null>(null)
const credential = ref({ name: '', origin: '', kind: 'bearer', secret: '' }), run = ref<APIIngestionRun | null>(null), runID = ref('')
const busy = ref(false), loading = ref(false), runLoading = ref(false), error = ref(''), notice = ref(''), sourceError = ref(''), credentialError = ref('')
let epoch = 0, readSequence = 0, listSequence = 0, timer: ReturnType<typeof setTimeout> | undefined, pendingStart: { id: string; version: number; key: string } | null = null
const controllers = new Set<AbortController>()
function controller() { const c = new AbortController(); controllers.add(c); return c }
const terminal = (state: string) => ['completed', 'partial', 'failed', 'timed_out', 'cancelled'].includes(state)
const statusLabel = (state: string) => ({ queued: '等待采集', running: '正在采集', completed: '完整候选已提交', partial: '部分完成', failed: '失败', timed_out: '已超时', cancelled: '已取消' } as Record<string, string>)[state] || state
function message(cause: unknown) { const e = cause as { response?: { status?: number } }; return [401, 403, 404].includes(e.response?.status || 0) ? '来源或凭据当前不可访问，请核对身份和权限。' : '操作未确认成功。请刷新状态或用同一请求重试，不会自动重新采集。' }
async function load(more = false) { const generation = epoch, sequence = ++listSequence, c = controller(); loading.value = true; if (!more) { sourceError.value = ''; credentialError.value = '' }
  const results = await Promise.allSettled([api.sources(more ? sourceCursor.value : '', c.signal), api.credentials(more ? credentialCursor.value : '', c.signal)])
  if (generation === epoch && sequence === listSequence) { const [a, b] = results; if (a.status === 'fulfilled' && a.value.data) { sources.value = more ? [...sources.value, ...a.value.data.items.filter(item => !sources.value.some(prior => prior.id === item.id))] : a.value.data.items; sourceCursor.value = a.value.data.next_cursor || '' } else sourceError.value = '来源列表读取失败。'; if (b.status === 'fulfilled' && b.value.data) { credentials.value = more ? [...credentials.value, ...b.value.data.items.filter(item => !credentials.value.some(prior => prior.id === item.id))] : b.value.data.items; credentialCursor.value = b.value.data.next_cursor || '' } else credentialError.value = '凭据列表读取失败。'; loading.value = false }; controllers.delete(c)
}
async function act(work: (signal: AbortSignal) => Promise<void>) { if (busy.value) return; const generation = epoch, c = controller(); busy.value = true; error.value = ''; notice.value = ''; try { await work(c.signal) } catch (cause) { if (generation === epoch) error.value = message(cause) } finally { controllers.delete(c); if (generation === epoch) busy.value = false } }
function newSource() { editing.value = { name: '', config: { url: '', credential_id: '', items_pointer: '/items', record_key: 'id', pagination: { mode: 'none', parameter: '', next_pointer: '', snapshot_pointer: '', snapshot_parameter: '' }, limits: { max_pages: 10, max_records: 1000, max_bytes: 8388608, max_page_bytes: 1048576, max_requests: 20, timeout_seconds: 120 } } } }
function edit(source: APISource) { editing.value = JSON.parse(JSON.stringify(source)) }
async function createCredential() { const generation = epoch, input = { ...credential.value }; await act(async signal => { await api.createCredential(input, signal); if (generation !== epoch) return; credential.value.secret = ''; notice.value = '凭据已加密保存。'; await load() }) }
async function disableCredential(id: string) { const generation = epoch; await act(async signal => { await api.disableCredential(id, signal); if (generation === epoch) { await load(); if (runID.value) await refreshRun() } }) }
async function saveSource() { if (!editing.value) return; const generation = epoch, input = JSON.parse(JSON.stringify(editing.value)) as NonNullable<typeof editing.value>; if (input.config.pagination.mode === 'none') { input.config.pagination.parameter = ''; input.config.pagination.next_pointer = '' }; await act(async signal => { if (input.id) await api.update(input.id, { name: input.name, expected_version: input.version!, config: input.config }, signal); else await api.create({ name: input.name, config: input.config }, signal); if (generation !== epoch) return; editing.value = null; notice.value = '来源版本已保存，尚未采集。'; await load() }) }
async function toggle(source: APISource) { const generation = epoch; await act(async signal => { await api.enabled(source.id, source.version, !source.enabled, signal); if (generation === epoch) { await load(); if (runID.value) await refreshRun() } }) }
async function start(source: APISource) { if (!pendingStart || pendingStart.id !== source.id || pendingStart.version !== source.version) pendingStart = { id: source.id, version: source.version, key: crypto.randomUUID() }; const input = pendingStart, generation = epoch; await act(async signal => { const result = await api.start(input.id, input.version, input.key, signal); if (generation !== epoch || !result.data) return; pendingStart = null; await openRun(result.data.id); await load() }) }
async function openRun(id: string) { const generation = epoch; await router.replace({ path: route.path, query: { run_id: id } }); if (generation !== epoch) return; if (runID.value !== id) { runID.value = id; run.value = null; await refreshRun() } }
async function refreshRun() { if (!runID.value) return; clearTimeout(timer); const generation = epoch, sequence = ++readSequence, id = runID.value, c = controller(); runLoading.value = true; try { const result = await api.run(id, c.signal); if (generation !== epoch || sequence !== readSequence || id !== runID.value) return; if (!result.data) throw new Error(); run.value = result.data; if (!terminal(result.data.status)) timer = setTimeout(() => void refreshRun(), 2000) } catch (cause) { if (generation === epoch && sequence === readSequence) { run.value = null; error.value = message(cause) } } finally { controllers.delete(c); if (generation === epoch && sequence === readSequence) runLoading.value = false } }
async function mutateRun(action: 'cancel' | 'resume') { const id = runID.value, generation = epoch; await act(async signal => { await api[action](id, signal); if (generation === epoch && id === runID.value) await refreshRun() }) }
function reset() { epoch++; readSequence++; listSequence++; clearTimeout(timer); controllers.forEach(c => c.abort()); controllers.clear(); sources.value = []; credentials.value = []; run.value = null; runID.value = ''; editing.value = null; credential.value.secret = ''; sourceCursor.value = ''; credentialCursor.value = ''; pendingStart = null; busy.value = false; loading.value = false; runLoading.value = false; error.value = ''; notice.value = '' }
watch(() => route.query.run_id, value => { runID.value = typeof value === 'string' ? value : ''; run.value = null; clearTimeout(timer); if (runID.value) void refreshRun() })
watch(() => `${auth.authEpoch}:${auth.user?.id}:${auth.currentTenant?.id}`, () => { reset(); void load() })
onMounted(() => { void load(); const id = route.query.run_id; if (typeof id === 'string') { runID.value = id; void refreshRun() } }); onBeforeUnmount(reset)
</script>
<style scoped>
.api-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:24px}.source-list,.credential-list{padding:0;list-style:none}.source-list li,.credential-list li{padding:18px 0;border-bottom:1px solid var(--border-color,#e5e7eb)}.source-list strong,.credential-list strong{display:block}.source-list span,.source-list small,.credential-list small{display:block;margin-top:6px;color:var(--text-secondary,#64748b);overflow-wrap:anywhere}.source-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}.api-wide{grid-column:1/-1}.receipt-stats{display:flex;flex-wrap:wrap;gap:32px}.receipt-stats dt{font-size:12px;color:var(--text-secondary,#64748b)}.receipt-stats dd{font-size:24px;margin:8px 0}details{margin-top:18px}summary{cursor:pointer;margin-bottom:12px}code{display:block;overflow-wrap:anywhere;font-size:11px}.api-sources fieldset{border:0;padding:0;min-width:0}.api-sources input,.api-sources select{width:100%}@media(max-width:800px){.api-grid{grid-template-columns:1fr}.receipt-stats{gap:20px}}
</style>
